            "ink" to 0xFF1F1A16.toInt(),
            "surface" to 0xFFFFFFFF.toInt(),
            "surfaceHi" to 0xFFFBEFE4.toInt(),
            "primary" to 0xFFC25100.toInt(),
            "onPrimary" to 0xFFFFFFFF.toInt(),
